from typing import Dict, List

def histogram(test: str) -> Dict[str, int]:
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Handle empty input string
    if not test or not test.strip():
        return {}

    # Split the string by spaces and filter out empty strings
    letters = [char for char in test.split() if char]

    # Count frequency of each letter
    freq = {}
    for letter in letters:
        freq[letter] = freq.get(letter, 0) + 1

    # If no valid letters, return empty dict
    if not freq:
        return {}

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Return all letters that have the maximum frequency
    return {letter: count for letter, count in freq.items() if count == max_freq}

